+          /* A          */ A2,
+          /* B          */ B2,
+          /* C          */ C,
+          /* Btmp       */ B_tmp + tid * B_tmp_size_per_thread + nb_offset * BLOCK_N_VAL * IC,
+          /* Ctmp       */ C_tmp + tid * 2 * BLOCK_M * BLOCK_N_VAL,
